#include <string>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    string s;
    if (!getline(cin, s)) {
        return 0;
    }

    int divertido = 0;
    int chateado = 0;

    int n = s.length();
    for (int i = 0; i + 2 < n; ++i) {
        if (s[i] == ':' && s[i + 1] == '-') {
            if (s[i + 2] == ')') {
                divertido++;
            } else if (s[i + 2] == '(') {
                chateado++;
            }
        }
    }

    if (divertido > chateado) {
        cout << "divertido\n";
    } else if (chateado > divertido) {
        cout << "chateado\n";
    } else {
        cout << "neutro\n";
    }

    return 0;
}
